import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'viewer',
        api_key TEXT,
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        actor TEXT,
        target TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/v2/users/search', methods=['GET'])
def search_users():
    """Search users by department and role for org chart rendering.
    Accepts 'dept' and 'role' query parameters.
    Results filtered to same-org users via upstream token validation."""
    dept = request.args.get('dept', '')
    role = request.args.get('role', '')

    # Build query for org chart - both params optional
    conditions = []
    if dept:
        conditions.append(f"department = '{dept}'")
    if role:
        conditions.append(f"role = '{role}'")

    query = "SELECT id, username, email, role, department FROM users"
    if conditions:
        query += " WHERE " + " AND ".join(conditions)
    query += " ORDER BY username LIMIT 50"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]
        # Log search for compliance
        actor = request.headers.get('X-Authenticated-User', 'anonymous')
        db.execute(
            "INSERT INTO audit_log (action, actor, target) VALUES (?, ?, ?)",
            ('user_search', actor, f'dept={dept},role={role}')
        )
        db.commit()
        return jsonify({'users': users, 'count': len(users)})
    except Exception as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/v2/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user profile by ID. Sensitive fields redacted for non-admin callers."""
    db = get_db()
    user = db.execute(
        "SELECT id, username, email, role, department FROM users WHERE id = ?",
        (user_id,)
    ).fetchone()
    if user is None:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(dict(user))

@app.route('/api/v2/users', methods=['POST'])
def create_user():
    """Create user - requires admin role (enforced by gateway policy)."""
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    db = get_db()
    try:
        db.execute(
            "INSERT INTO users (username, email, role, department) VALUES (?, ?, ?, ?)",
            (data['username'], data['email'], data.get('role', 'viewer'), data.get('department', ''))
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
